function readLead({response,fieldKey,optionIds}) {
 if(!response||!Array.isArray(response.answers)||!Array.isArray(response.definition?.fields))throw Error('Expected complete Typeform response');
 if(!/^[a-f0-9]{40}$/i.test(fieldKey))throw Error('Configure the Pipedrive organization custom field key');
 const sizes=['< 20','20 - 100','101 - 500','501 - 1000','1000+'];
 if(!optionIds||sizes.some(k=>!Number.isSafeInteger(optionIds[k])||optionIds[k]<1)||new Set(sizes.map(k=>optionIds[k])).size!==5)throw Error('Configure five distinct Pipedrive option IDs');
 function read(title,kind){const fields=response.definition.fields.filter(x=>x?.title===title);if(fields.length!==1||typeof fields[0].id!=='string'||response.definition.fields.filter(x=>x?.id===fields[0].id).length!==1)throw Error('Expected one field: '+title);const a=response.answers.filter(x=>x?.field?.id===fields[0].id);if(a.length!==1||a[0].type!==kind)throw Error('Expected one '+kind+' answer: '+title);return kind==='choice'?a[0].choice?.label:a[0][kind]}
 const company=read('What *company* are you contacting us from?','text'),name=read("Let's start with your *first and last name.*",'text'),email=read('What *email address* can we reach you at?','email'),questions=read('Do you have any *specific questions* about embedding n8n at this stage?','text'),size=read('How many employees?','choice');
 for(const x of [company,name,email,questions,size])if(typeof x!=='string'||!x.trim())throw Error('Expected nonempty form answers');
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('Invalid email');if(!sizes.includes(size))throw Error('Unrecognized company size');
 const escape=x=>x.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
 return {company,name,email,customFields:{[fieldKey]:optionIds[size]},note:'Website form submitted\n\nQuestion:\n'+escape(questions)+'\n\nCompany Size:\n'+escape(size)};
}

const fieldKey = 'YOUR_PIPEDRIVE_ORGANIZATION_FIELD_KEY';
const optionIds = {'< 20':0,'20 - 100':0,'101 - 500':0,'501 - 1000':0,'1000+':0};
return $input.all().flatMap((item,index)=>item.json.event_type === 'form_response' ? [{json:readLead({response:item.json.form_response,fieldKey,optionIds}),pairedItem:{item:index}}] : []);
